<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!academy_ready())redirect('upgrade-multiverse-academy.php');$u=user();
$s=db()->prepare("SELECT c.*,(SELECT COUNT(*) FROM academy_lessons l WHERE l.course_id=c.id) lesson_count,(SELECT COUNT(*) FROM academy_enrollments e WHERE e.course_id=c.id AND e.status<>'cancelled') enrollment_count FROM academy_courses c WHERE c.owner_user_id=? OR EXISTS(SELECT 1 FROM academy_instructors i WHERE i.course_id=c.id AND i.user_id=?) ORDER BY c.updated_at DESC");$s->execute([$u['id'],$u['id']]);$owned=$s->fetchAll();
$s=db()->prepare("SELECT c.*,e.status enrollment_status,e.progress_percent FROM academy_enrollments e JOIN academy_courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC");$s->execute([$u['id']]);$enrolled=$s->fetchAll();
app_header('My Academy');?><section class="dashboard-hero"><p class="eyebrow">MULTIVERSE ACADEMY</p><h1>My Academy</h1><p>Manage courses you teach and continue courses you are learning.</p><p><a class="button primary" href="create.php">Create Course</a> <a class="button ghost" href="index.php">Browse Courses</a></p></section><section class="app-card"><h2>Courses I Teach</h2><div class="course-list"><?php foreach($owned as $c):?><article class="list-card"><div><p class="eyebrow"><?=e(strtoupper($c['status']))?></p><h3><?=e($c['title'])?></h3><p><?=(int)$c['lesson_count']?> lessons · <?=(int)$c['enrollment_count']?> learners</p></div><a class="button primary small" href="manage.php?id=<?=(int)$c['id']?>">Manage</a></article><?php endforeach?><?php if(!$owned):?><p class="muted">You have not created a course yet.</p><?php endif?></div></section><section class="app-card"><h2>My Learning</h2><div class="course-list"><?php foreach($enrolled as $c):?><article class="list-card"><div><p class="eyebrow"><?=e(strtoupper(str_replace('_',' ',$c['enrollment_status'])))?></p><h3><a href="view.php?slug=<?=urlencode($c['slug'])?>"><?=e($c['title'])?></a></h3><div class="progress"><span style="width:<?=(int)$c['progress_percent']?>%"></span></div><p><?=(int)$c['progress_percent']?>% complete</p></div></article><?php endforeach?><?php if(!$enrolled):?><p class="muted">You are not enrolled in any courses.</p><?php endif?></div></section><?php app_footer();
